import{_ as t,o as a,c as l,a5 as o}from"./chunks/framework.DOB-AMqW.js";const h=JSON.parse('{"title":"Vault Nest Data Deletion","description":"Standalone instructions for deleting Vault Nest data.","frontmatter":{"title":"Vault Nest Data Deletion","description":"Standalone instructions for deleting Vault Nest data.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/vault-nest.md","filePath":"data-deletion/vault-nest.md"}'),s={name:"data-deletion/vault-nest.md"};function n(d,e,r,i,c,p){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="delete-vault-nest-data" tabindex="-1">Delete Vault Nest Data <a class="header-anchor" href="#delete-vault-nest-data" aria-label="Permalink to &quot;Delete Vault Nest Data&quot;">​</a></h1><p>Vault Nest has no online account or developer-operated cloud vault. App data is stored on your device and can be removed without contacting the developer.</p><h2 id="delete-individual-items" tabindex="-1">Delete individual items <a class="header-anchor" href="#delete-individual-items" aria-label="Permalink to &quot;Delete individual items&quot;">​</a></h2><p>Move an item to <strong>Trash</strong>, then permanently delete it from Trash or empty Trash. Otherwise it is removed automatically after the configured 7, 30, or 90-day retention period. Selecting <strong>Never</strong> keeps trashed items until you delete them.</p><h2 id="delete-all-saved-vault-items" tabindex="-1">Delete all saved vault items <a class="header-anchor" href="#delete-all-saved-vault-items" aria-label="Permalink to &quot;Delete all saved vault items&quot;">​</a></h2><p>Open <strong>Settings → Data → Clear vault database</strong> and confirm the warning. This permanently deletes saved vault items while retaining the master-password setup and preferences.</p><h2 id="delete-the-account-and-complete-local-database" tabindex="-1">Delete the account and complete local database <a class="header-anchor" href="#delete-the-account-and-complete-local-database" aria-label="Permalink to &quot;Delete the account and complete local database&quot;">​</a></h2><p>Open the Vault Nest navigation menu, select <strong>Remove account</strong>, enter the current master password, acknowledge the warning, and confirm deletion. This removes the local vault database, preferences, biometric unlock material, temporary credential-copy values, and encrypted intrusion evidence.</p><p>You can also clear Vault Nest&#39;s storage from Android system settings or uninstall the app.</p><h2 id="delete-files-outside-the-app" tabindex="-1">Delete files outside the app <a class="header-anchor" href="#delete-files-outside-the-app" aria-label="Permalink to &quot;Delete files outside the app&quot;">​</a></h2><p>Removing app data does not delete <code>.vaultpack</code> backups, plaintext CSV exports, downloaded evidence images, clipboard contents, or copies shared with other apps or storage providers. Delete those separately from every location where you saved or shared them.</p><p>Because the developer does not hold a cloud vault, emailing support cannot delete data stored on your device.</p>',12)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
